import{_ as a,o as n,a as p,b as l}from"./app.BGziXukh.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"mmad计算配置","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_config/mmad_compute_config"},{"text":"disable_hf32","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_config/disable_hf32"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_config/disable_hf32.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_config/disable_hf32.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1794877794000}'),c={name:"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_config/disable_hf32.md"};function t(e,s,_,o,i,w){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>disable_hf32</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>关闭HF32模式。HF32模式用于矩阵计算，详细说明可参考<a href="../mmad_compute_key_features/hf32.html">HF32</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">disable_hf32</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>本接口需在矩阵乘加计算前调用，以确保模式配置在矩阵乘加计算过程中生效。</li><li>与<a href="enable_hf32.html">enable_hf32</a>作用相反，二者不同时生效。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例先开启HF32模式并完成16×16 float矩阵乘法，矩阵A和矩阵B的所有元素均为1，结果矩阵的每个元素均为16；计算完成后关闭HF32模式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>

<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">single_core_m</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">base_k</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">base_n</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__cube__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">matmul_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">c</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>
<span class="w">    </span><span class="n">init_soc_state</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// Split the output matrix by m and n tiles across Cube cores.</span>
<span class="w">    </span><span class="c1">// Map block_idx to this core&#39;s output tile: m_iter_idx iterates fastest over the m-axis splits</span>
<span class="w">    </span><span class="c1">// (one core computes one base_m x base_n output tile).</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m_iter</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">m</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">single_core_m</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m_iter_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="n">m_iter</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n_iter_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">m_iter</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// Create GM tensors and slice the tile handled by the current core.</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">gm_a</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">a</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">gm_b</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">b</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">gm_c</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">c</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">global_a</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gm_a</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">make_coord</span><span class="p">(</span><span class="n">m_iter_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">single_core_m</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">make_shape</span><span class="p">(</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">global_b</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gm_b</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">n_iter_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_n</span><span class="p">),</span><span class="w"> </span><span class="n">make_shape</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">global_c</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gm_c</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">make_coord</span><span class="p">(</span><span class="n">m_iter_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">single_core_m</span><span class="p">,</span><span class="w"> </span><span class="n">n_iter_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_n</span><span class="p">),</span><span class="w"> </span><span class="n">make_shape</span><span class="p">(</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">));</span>

<span class="w">    </span><span class="c1">// Layout per level: GM uses nd_ext (linear row-major); L1 A/B, L0A and L0C use the NZ fractal,</span>
<span class="w">    </span><span class="c1">// L0B uses the ZN fractal, matching each buffer&#39;s data format for the L1-&gt;L0 copies.</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1_a_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1_b_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0_a_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">base_k</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0_b_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">zn_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">base_k</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0_c_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">_16</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">);</span>

<span class="w">    </span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l1_a_buf</span><span class="p">[</span><span class="n">base_m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k</span><span class="p">];</span>
<span class="w">    </span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l1_b_buf</span><span class="p">[</span><span class="n">k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_n</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ca__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l0_a_buf</span><span class="p">[</span><span class="n">base_m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_k</span><span class="p">];</span>
<span class="w">    </span><span class="n">__cb__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l0_b_buf</span><span class="p">[</span><span class="n">base_k</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_n</span><span class="p">];</span>
<span class="w">    </span><span class="n">__cc__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">l0_c_buf</span><span class="p">[</span><span class="n">base_m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_n</span><span class="p">];</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1_a_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l1_a_buf</span><span class="p">),</span><span class="w"> </span><span class="n">l1_a_layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1_b_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l1_b_buf</span><span class="p">),</span><span class="w"> </span><span class="n">l1_b_layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0_a_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l0_a_buf</span><span class="p">),</span><span class="w"> </span><span class="n">l0_a_layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0_b_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l0_b_buf</span><span class="p">),</span><span class="w"> </span><span class="n">l0_b_layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0_c_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l0_c_buf</span><span class="p">),</span><span class="w"> </span><span class="n">l0_c_layout</span><span class="p">);</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copy_gm2l1_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_gm_to_l1</span><span class="p">{},</span><span class="w"> </span><span class="n">gm_to_l1_trait_default</span><span class="p">{});</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copy_l12l0a_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l1_to_l0a</span><span class="p">{},</span><span class="w"> </span><span class="n">l1_to_l0a_trait_default</span><span class="p">{});</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copy_l12l0b_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l1_to_l0b</span><span class="p">{},</span><span class="w"> </span><span class="n">l1_to_l0b_trait_default</span><span class="p">{});</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copy_l0c2gm_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l0c_to_gm</span><span class="p">{},</span><span class="w"> </span><span class="n">l0c_to_gm_trait_default</span><span class="p">{});</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">mmad_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mmad</span><span class="p">(</span><span class="n">mmad_operation</span><span class="p">{},</span><span class="w"> </span><span class="n">mmad_trait_default</span><span class="p">{});</span>

<span class="w">    </span><span class="c1">// K-axis loop count (whole base_k tiles; this sample requires k divisible by base_k)</span>
<span class="w">    </span><span class="c1">// and the event ids serializing buffer accesses between pipelines.</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k_loop</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">base_k</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">l1_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pipe_mte2_l1_index_mutex</span><span class="p">(</span><span class="n">l1_index</span><span class="p">);</span>
<span class="w">    </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">PIPE_MTE1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pipe_mte1_l1_index_mutex</span><span class="p">(</span><span class="n">l1_index</span><span class="p">);</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">l0_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">l0c_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="w">    </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pipe_m_l0c_index_mutex</span><span class="p">(</span><span class="n">l0c_index</span><span class="p">);</span>
<span class="w">    </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">PIPE_FIX</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pipe_fix_l0c_index_mutex</span><span class="p">(</span><span class="n">l0c_index</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// Fill the unused L1 tail once to make padding deterministic before MTE1 loads.</span>
<span class="w">    </span><span class="n">fill</span><span class="p">(</span><span class="n">l1_a_tensor</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="n">fill</span><span class="p">(</span><span class="n">l1_b_tensor</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>

<span class="w">    </span><span class="c1">// Lock L0C for the whole K-accumulation of this output tile.</span>
<span class="w">    </span><span class="n">pipe_m_l0c_index_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// MTE2 stage: move the current core&#39;s full A/B tiles from GM to L1 once.</span>
<span class="w">    </span><span class="n">pipe_mte2_l1_index_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">copy_gm2l1_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l1_a_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">global_a</span><span class="p">);</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">copy_gm2l1_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l1_b_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">global_b</span><span class="p">);</span>
<span class="w">    </span><span class="n">pipe_mte2_l1_index_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="w">    </span><span class="n">pipe_mte1_l1_index_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k_iter</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">k_iter</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">k_loop</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">k_iter</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">PIPE_MTE1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pipe_mte1_l0_index_mutex</span><span class="p">(</span><span class="n">l0_index</span><span class="p">);</span>
<span class="w">        </span><span class="n">mutex</span><span class="o">&lt;</span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="w"> </span><span class="n">pipe_m_l0_index_mutex</span><span class="p">(</span><span class="n">l0_index</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// MTE1 stage: load one base_k slice from L1 to L0.</span>
<span class="w">        </span><span class="n">pipe_mte1_l0_index_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>
<span class="w">        </span><span class="n">copy</span><span class="p">(</span>
<span class="w">            </span><span class="n">copy_l12l0a_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0_a_tensor</span><span class="p">,</span>
<span class="w">            </span><span class="n">l1_a_tensor</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">k_iter</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_k</span><span class="p">),</span><span class="w"> </span><span class="n">make_shape</span><span class="p">(</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">base_k</span><span class="p">)));</span>
<span class="w">        </span><span class="n">copy</span><span class="p">(</span>
<span class="w">            </span><span class="n">copy_l12l0b_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0_b_tensor</span><span class="p">,</span>
<span class="w">            </span><span class="n">l1_b_tensor</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">make_coord</span><span class="p">(</span><span class="n">k_iter</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_k</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">make_shape</span><span class="p">(</span><span class="n">base_k</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">)));</span>
<span class="w">        </span><span class="n">pipe_mte1_l0_index_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="w">        </span><span class="c1">// M stage: first k iteration initializes L0C (C = A*B), later ones accumulate (C += A*B).</span>
<span class="w">        </span><span class="n">pipe_m_l0_index_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>

<span class="w">        </span><span class="n">enable_hf32</span><span class="p">();</span>
<span class="w">        </span><span class="n">set_hf32_round_mode</span><span class="p">(</span><span class="n">hf32_round_mode</span><span class="o">::</span><span class="n">nearest_even</span><span class="p">);</span>
<span class="w">        </span><span class="n">set_mmad_direction</span><span class="p">(</span><span class="n">mmad_direction</span><span class="o">::</span><span class="n">m</span><span class="p">);</span>
<span class="w">        </span><span class="n">mmad_params</span><span class="w"> </span><span class="n">para</span><span class="p">{</span><span class="n">base_m</span><span class="p">,</span><span class="w"> </span><span class="n">base_n</span><span class="p">,</span><span class="w"> </span><span class="n">base_k</span><span class="p">,</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="o">::</span><span class="n">disable</span><span class="p">,</span><span class="w"> </span><span class="n">k_iter</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>

<span class="w">        </span><span class="n">mmad</span><span class="p">(</span><span class="n">mmad_atom</span><span class="p">.</span><span class="n">with</span><span class="p">(</span><span class="n">para</span><span class="p">),</span><span class="w"> </span><span class="n">l0_c_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0_a_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0_b_tensor</span><span class="p">);</span>

<span class="w">        </span><span class="n">pipe_m_l0_index_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">pipe_mte1_l1_index_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="w">    </span><span class="n">pipe_m_l0c_index_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="w">    </span><span class="n">disable_hf32</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// Store the completed output tile from L0C back to GM.</span>
<span class="w">    </span><span class="n">pipe_fix_l0c_index_mutex</span><span class="p">.</span><span class="n">lock</span><span class="p">();</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">copy_l0c2gm_atom</span><span class="p">,</span><span class="w"> </span><span class="n">global_c</span><span class="p">,</span><span class="w"> </span><span class="n">l0_c_tensor</span><span class="p">);</span>
<span class="w">    </span><span class="n">pipe_fix_l0c_index_mutex</span><span class="p">.</span><span class="n">unlock</span><span class="p">();</span>
<span class="w">    </span><span class="n">sync_pipe</span><span class="p">(</span><span class="n">PIPE_ALL</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const u=a(c,[["render",t]]);export{r as __pageData,u as default};
